import TropicSea_logo from 'TropicSea_logo.svg'
import './App.css';
import AnalysisTable from './components/AnalysisTable';
import Header from './components/Header';

function App() {
  return (
    <div className='App'>
        <Header/>
        <TropicSea_logo/>
      <div className='card-header'></div>
      <div className='card-body'>
        <AnalysisTable/> 
      </div>
    </div>
  );
}

export default App;
